			text = [=[Greta Mosshoof is a druid of the {link:emerald-circle}Emerald Circle{/link}, and she prays to the Earth Mother. Where others of her circle seek to heal the forest, she has taken on the task of striking at the cause of its sickness. Her enemy is the {link:shadow-council}Shadow Council{/link} in {link:jaedenar}Jaedenar{/link}, and she means to cut off its head.]=],
		},
		{
			title = "Significance",
			text = [=[Greta is the planner of the Circle's war against {link:jaedenar}Jaedenar{/link}. She understands that {link:shadow-council}the Council{/link} cannot be fought blind, and she is patient enough to learn before she strikes. She is also the keeper of a greater hope: the gathering of a cure that may one day heal the trees and creatures of {link:felwood}Felwood{/link}.]=],
		},
		{
			title = "Deeds",
			text = [=[• She tested the resolve of those who came to help her against the cultists of {link:jaedenar}Jaedenar{/link}.
• She had the corrupt water of the moonwell of Jaedenar purified by the spirits of water.
• She scried into Shadow Hold and learned who led {link:shadow-council}the Council{/link}.
• She sent her allies against {link:shadow-lord-fel-dan}Shadow Lord Fel'dan{/link} and his servants.
• She sought the blood of the green drake {link:morphaz}Morphaz{/link} for the second cure of {link:felwood}Felwood{/link}.]=],
		},
	},
	chapters = {
		{
			key = "water-against-fire",
			title = "Water Against Fire",
			hint = [=[Take the water of Jaedenar's moonwell to be purified, and use it on the braziers of Shadow Hold.]=],
			unlock = {
				{ type = "quest", id = 5157 },
				{ type = "quest", id = 5158 },
				{ type = "quest", id = 5159 },
				{ type = "quest", id = 5165 },
			},
			text = [=[The Council shielded {link:jaedenar}Shadow Hold{/link} with spells that burned in four braziers. Greta sent for water from the corrupted moonwell at Jaedenar's heart, then sent it south to an old friend, a shaman who dwells by the sea south of {link:ratchet}Ratchet{/link}. The spirits of water heard the shaman and blessed the cause. With the purified water, the flames were doused. For a short while before the warlocks renewed their wards, Greta could see into the Hold.]=],
		},
		{
			key = "the-head-of-the-serpent",
			title = "The Head of the Serpent",
			hint = "Strike at the mortal who leads the Shadow Council.",
			unlock = {
				{ type = "quest", id = 5242 },
			},
			text = [=[What Greta saw told her there was no clever way in. {link:shadow-lord-fel-dan}Fel'dan{/link}, the Shadow Lord, was the mortal in command below, and he was the one making pacts with the Legion. She sent her allies straight down to him. When his head came back to her, she praised the Earth Mother. She hoped that without him {link:shadow-council}the Council{/link} would turn on itself.]=],
		},
		{
			key = "the-second-cure",
			title = "The Second Cure",
			hint = [=[Bring her the blood of the drake Morphaz from the sunken temple.]=],
			unlock = {
				{ type = "quest", id = 8257 },
			},
			text = [=[The green drake {link:morphaz}Morphaz{/link} is said to be immune to every poison and disease, and many druids died to learn it. Greta wanted his blood. When it came, she could hardly believe it. It would take a lifetime, she said, to undo what had happened in {link:felwood}Felwood{/link}, but at last the Circle had the means to begin.]=],
		},
