	hint = [=[Cloak yourself in shadow and seek the dreadlord at the bottom of Jaedenar.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Lord Banehollow is a dreadlord who holds court in the depths of {link:jaedenar}Jaedenar{/link}, the seat of the {link:shadow-council}Shadow Council{/link}. He is old, patient and cruel. The warlocks of the Council come and go before him, and only those who wear the Council's own shadow may approach him unharmed.]=],
		},
		{
			title = "Significance",
			text = [=[Banehollow is the demon behind the mortal warlocks of {link:jaedenar}Jaedenar{/link}, and he has rivals even among his own kind. Chief among them is Lord Hel'nurath, who rules a domain called Xoroth beyond this world and breeds there the famed dreadsteeds. Banehollow keeps a store of stardust from Xoroth, and warlocks who wish to open a way to that realm must bargain with him for it.]=],
