			hint = [=[Come to Jaedenar disguised by the shadowy potions of the Burning Steppes.]=],
			unlock = {
				{ type = "quest", id = 7623 },
			},
			text = [=[The goblin {link:gorzeeki-wildeyes}Gorzeeki Wildeyes{/link} brews potions that let their drinker pass for one of the {link:shadow-council}Shadow Council{/link}. Those who drink them may walk through {link:jaedenar}Jaedenar{/link} and stand before Banehollow. He does not welcome them warmly. His patience, he says, spans millennia, and still they may have no more than an instant of it.]=],
