			hint = "Prove your service to the dreadlord.",
			unlock = {
				{ type = "quest", id = 7624 },
			},
			text = [=[{link:ulathek}Ulathek{/link} grovelled before his master while he plotted with Hel'nurath, who hoped to take Banehollow's power in {link:felwood}Felwood{/link}. Banehollow knew. He wanted Ulathek told so, and he wanted to watch the fear. Then he wanted the heart, which he meant to let rot for a week before he ate it.]=],
