			hint = "Buy the stardust of Xoroth from the dreadlord's servant.",
			unlock = {
				{ type = "quest", id = 7625 },
			},
			text = [=[Banehollow guessed at once why a warlock wanted stardust: to open a portal to his rival's domain and steal one of its dreadsteeds. The idea did not trouble him. He let his servant Ur'dan sell the stardust, for a price. It went back to {link:gorzeeki-wildeyes}Gorzeeki{/link}, and from him to {link:mor-zul-bloodbringer}Mor'zul Bloodbringer{/link}, who needed it for his ink.]=],
