Add({
	kind = "figure",
	id = "tichondrius",
	title = "Tichondrius",
	subtitle = "Dreadlord of the Burning Legion",
	tier = "A",
	region = "felwood",
	allegiance = "Burning Legion",
	unlock = {
		{ type = "read" },
		{ type = "quest", id = 4261 },
	},
	hint = [=[Learn who poisoned the northern forest with the Skull of Gul'dan.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Tichondrius was a dreadlord, one of the nathrezim who serve the {link:burning-legion}Burning Legion{/link}. In the {link:third-war}Third War{/link} he was among the demons who guided the {link:scourge}Scourge{/link} in the Legion's name, and he gave his commands to the death knight {link:arthas-menethil}Arthas Menethil{/link}. When the Legion came to {link:kalimdor}Kalimdor{/link}, he carried the Skull of {link:gul-dan}Gul'dan{/link} into the northern forest and poisoned it with the skull's dark power. That forest is {link:felwood}Felwood{/link}. He was slain there by {link:illidan-stormrage}Illidan Stormrage{/link}.]=],
		},
		{
			title = "Significance",
			text = [=[Of all the demons of the {link:third-war}Third War{/link}, Tichondrius left the deepest mark on the land itself. {link:archimonde}Archimonde{/link} fell at {link:mount-hyjal}Mount Hyjal{/link} and his host was broken, but the corruption Tichondrius sowed did not die with him. Every mad {link:furbolgs}furbolg{/link}, every blighted treant and every foul moonwell in {link:felwood}Felwood{/link} is part of his legacy. His death also changed {link:illidan-stormrage}Illidan{/link} forever: to defeat him, Illidan took the power of the skull into himself, and his people banished him for it.]=],
		},
		{
			title = "The Scourge and the Legion",
			text = [=[The Lich King made the {link:scourge}Scourge{/link}, but he did not make it free. The dreadlords of the Legion watched over it, and Tichondrius was among them. After {link:arthas-menethil}Arthas{/link} slew his father and gave himself wholly to the Scourge, Tichondrius tested the prince's loyalty and gave him his tasks. Arthas carried the remains of the necromancer {link:kel-thuzad}Kel'Thuzad{/link} to the Sunwell of {link:quel-thalas}Quel'Thalas{/link}, where Kel'Thuzad was raised as a lich. Kel'Thuzad in turn called {link:archimonde}Archimonde{/link} into the world at {link:dalaran}Dalaran{/link}. With the Legion's lord come at last, the Scourge had served its purpose, and the demons turned to {link:kalimdor}Kalimdor{/link}.]=],
		},
		{
			title = "The Poisoning of the Forest",
			text = [=[{link:archimonde}Archimonde{/link}'s host marched on {link:mount-hyjal}Mount Hyjal{/link} and the World Tree {link:nordrassil}Nordrassil{/link}. Tichondrius came to the northern forests with the {link:skull-of-gul-dan}Skull of Gul'dan{/link}, the remains of the warlock who had first bound the orcs to the Legion. The skull still held much of {link:gul-dan}Gul'dan{/link}'s fel power, and Tichondrius used it to corrupt the woods around him. The trees blackened and the waters turned. Beasts and furbolgs went mad. Infernals fell burning from the sky, and the ancients who guarded the forest were destroyed.]=],
		},
		{
			title = "The Death of the Dreadlord",
			text = [=[{link:tyrande-whisperwind}Tyrande Whisperwind{/link} had freed {link:illidan-stormrage}Illidan{/link} from his long imprisonment to fight the demons. Illidan learned of the skull and went after it. He took it, and he consumed its power. It changed him: he grew horns and great dark wings, and he became part demon himself. With that power, he slew Tichondrius. The victory cost him everything else. {link:malfurion-stormrage}Malfurion Stormrage{/link} could not forgive what his brother had become, and he banished Illidan from the forests of the night elves.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle tells how Tichondrius came to hold the skull, or how long he dwelt in the forest before {link:illidan-stormrage}Illidan{/link} found him.]=],
		},
	},
	chapters = {
		{
			key = "the-memory-of-the-ancients",
			title = "The Memory of the Ancients",
			hint = "Lead the spirit of an ancient out of the corrupted forest.",
			unlock = {
				{ type = "quest", id = 4261 },
			},
			text = [=[The ancient spirit {link:arei}Arei{/link} still remembers the forest before the Legion came. She remembers the infernals, the destruction and the chaos. She remembers that the {link:skull-of-gul-dan}skull of Gul'dan{/link} made sure that nothing in the forest was spared. Even as a spirit, she cannot escape the suffering of the land. She asks only to be led out of it, so that she may rest.]=],
		},
	},
	mentions = {
		{
			text = "Ancient Spirit",
			unlock = {
				{ type = "quest", id = 4261 },
			},
		},
	},
	bonds = {
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "his slayer" },
		{ id = "gul-dan", name = "Gul'dan", note = "the warlock whose skull he used" },
		{ id = "archimonde", name = "Archimonde", note = "his master in the Third War" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "the death knight he commanded" },
		{ id = "arei", name = "Arei", note = "an ancient who remembers his corruption" },
	},
})

Add({
	kind = "topic",
	id = "skull-of-gul-dan",
	title = "Skull of Gul'dan",
	aliases = { "skull of Gul'dan" },
	category = "artifact",
	region = "felwood",
	unlock = {
		{ type = "read" },
		{ type = "quest", id = 4261 },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Skull of Gul'dan was the skull of the {link:orcs}orc{/link} warlock {link:gul-dan}Gul'dan{/link}, founder of the {link:shadow-council}Shadow Council{/link}. It survived the warlock's death in the Tomb of {link:sargeras}Sargeras{/link} and kept much of his fel power. In the {link:third-war}Third War{/link}, the dreadlord {link:tichondrius}Tichondrius{/link} brought it to {link:kalimdor}Kalimdor{/link} and used it to corrupt the northern forest. {link:illidan-stormrage}Illidan Stormrage{/link} took it from him and consumed its power, and with it he became a creature half demon.]=],
		},
		{
			title = "Its Legacy",
			text = [=[The skull no longer exists, but its work remains. The forest it poisoned is called {link:felwood}Felwood{/link}. The spirits of the ancients remember that it spared nothing, and the druids of the {link:emerald-circle}Emerald Circle{/link} still struggle against what it left behind.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "shadow-council",
	title = "Shadow Council",
	aliases = { "the Council" },
	category = "group",
	unlock = {
		{ type = "read" },
		{ type = "quest", id = 5155 },
		{ type = "quest", id = 7623 },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Shadow Council is a secret order of warlocks who serve the {link:burning-legion}Burning Legion{/link}. It was born among the orcs of Draenor, and it outlived the {link:horde}Horde{/link} it once ruled. Today its seat is {link:jaedenar}Jaedenar{/link} in {link:felwood}Felwood{/link}, and its sects are scattered across the world.]=],
		},
		{
			title = "Origins",
			text = [=[The demon lord {link:kil-jaeden}Kil'jaeden{/link} chose the warlock {link:gul-dan}Gul'dan{/link} as his servant among the orcs. Gul'dan gathered the most ambitious of his fellow warlocks into a hidden council. It ruled the orcish clans from behind a puppet warchief and led them to drink the blood of {link:mannoroth}Mannoroth{/link}. Through Gul'dan it opened the {link:dark-portal}Dark Portal{/link}.]=],
		},
		{
			title = "The Fall",
			text = [=[In the days after the {link:first-war}First War{/link}, the Council made its seat in {red:blackrock-spire}Blackrock Spire{/red}. {link:orgrim-doomhammer}Orgrim Doomhammer{/link} turned on it there, slew most of its members and took {link:gul-dan}Gul'dan{/link} captive. Gul'dan later betrayed the {link:horde}Horde{/link} and died. The Council was believed to have died with him.]=],
		},
		{
			title = "In the Present Day",
			text = [=[It did not. In {link:jaedenar}Jaedenar{/link}, the {link:shadow-lord-fel-dan}Shadow Lord Fel'dan{/link} leads the order and makes its pacts with the Legion, while a dreadlord holds court in the depths below. The Council is blamed for many evils in {link:felwood}Felwood{/link} and abroad. Its mark appears among the warlocks of the {link:arathi-highlands}Arathi Highlands{/link}. In {link:orgrimmar}Orgrimmar{/link}, the {link:burning-blade}Burning Blade{/link} and the Searing Blade serve its purposes, and the Shadowsworn of the {link:blasted-lands}Blasted Lands{/link} are its heirs. {link:thrall}Thrall{/link} knows it lives, and he means to find it.]=],
		},
	},
})

