			title = "Summary",
			text = [=[The Emerald Circle is a fellowship of druids of the {link:cenarion-circle}Cenarion Circle{/link} who have committed themselves to {link:felwood}Felwood{/link}. Night elves and {link:tauren}tauren{/link} serve in it together, and they welcome friends of the {link:alliance}Alliance{/link} and the {link:horde}Horde{/link} alike. From the {link:emerald-sanctuary}Emerald Sanctuary{/link}, they study the corruption and try to reverse it.]=],
