	sections = {
		{
			title = "Summary",
			text = [=[The Timbermaw are the one tribe of {link:furbolgs}furbolgs{/link} that has escaped the corruption. They dwell in {link:timbermaw-hold}Timbermaw Hold{/link}, the tunnels between {link:felwood}Felwood{/link} and {link:winterspring}Winterspring{/link}, and they guard them against all comers.]=],
		},
		{
			title = "A Wary People",
			text = [=[The Timbermaw trust very few. Many travellers now kill any {link:furbolgs}furbolg{/link} they see, without asking whether it is friend or foe. The Timbermaw have learned from this. They welcome only those who prove themselves against the corrupted tribes, the {link:deadwood-furbolgs}Deadwood{/link} of {link:felwood}Felwood{/link} and the {link:winterfall-furbolgs}Winterfall{/link} of {link:winterspring}Winterspring{/link}. It grieves them to fight their own kin, but they do it. {link:magni-bronzebeard}King Magni{/link} of {link:ironforge}Ironforge{/link} and the Warchief of the {link:horde}Horde{/link} have both tried to reach them in the past.]=],
		},
		{
			title = "Their Hope",
			text = [=[The Timbermaw believe that the {link:winterfall-furbolgs}Winterfall{/link} are ruled by a demon. If it were destroyed, the healing of the Winterfall could begin, and the Hold would be safe for years to come.]=],
		},
	},
})

